import{elements}from"./elements.min.js";import{state,saveState}from"./state.min.js";import{renderPlayList}from"./ui.min.js";import{loadItems}from"./playlist.min.js";const sortOptions=[{field:"name",dir:"asc",label:"Name (↑)"},{field:"name",dir:"desc",label:"Name (↓)"},{field:"timestamp",dir:"desc",label:"Date (↓)"},{field:"timestamp",dir:"asc",label:"Date (↑)"},{field:"finalSize",dir:"desc",label:"Size (↓)"},{field:"finalSize",dir:"asc",label:"Size (↑)"}];let currentSortIndex=0;function initializeSortButton(buttonElement){if(state.sortPreferences){currentSortIndex=sortOptions.findIndex((option=>option.field===state.sortPreferences.field&&option.dir===state.sortPreferences.direction));if(currentSortIndex===-1)currentSortIndex=0}updateSortButtonText(buttonElement)}function updateSortButtonText(buttonElement){buttonElement.textContent=`Sort by ${sortOptions[currentSortIndex].label}`;buttonElement.setAttribute("aria-label",`Sort by ${sortOptions[currentSortIndex].label}`)}function sortItems(items,preferences=null){if(!items||items.length===0)return items;if(!preferences){preferences={field:sortOptions[currentSortIndex].field,direction:sortOptions[currentSortIndex].dir}}const itemsCopy=[...items];const{field:field,direction:direction}=preferences;return itemsCopy.sort(((a,b)=>{let valueA=a[field];let valueB=b[field];if(valueA===undefined||valueA===null){if(typeof valueB==="string")valueA="";else valueA=0}if(valueB===undefined||valueB===null){if(typeof valueA==="string")valueB="";else valueB=0}if(typeof valueA==="string"&&typeof valueB==="string"){return direction==="asc"?valueA.toLowerCase().localeCompare(valueB.toLowerCase()):valueB.toLowerCase().localeCompare(valueA.toLowerCase())}else{return direction==="asc"?valueA-valueB:valueB-valueA}}))}function cycleSortOrder(buttonElement){currentSortIndex=(currentSortIndex+1)%sortOptions.length;updateSortButtonText(buttonElement);updateSortPreferences()}function cycleSortOrderReverse(buttonElement){currentSortIndex=(currentSortIndex-1+sortOptions.length)%sortOptions.length;updateSortButtonText(buttonElement);updateSortPreferences()}function updateSortPreferences(){const currentItem=state.items[state.currentIndex];state.sortPreferences={field:sortOptions[currentSortIndex].field,direction:sortOptions[currentSortIndex].dir};state.items=sortItems(state.items,state.sortPreferences);if(currentItem){const newIndex=state.items.findIndex((item=>item.id===currentItem.id));state.currentIndex=newIndex!==-1?newIndex:0}saveState();renderPlayList()}export{cycleSortOrder,cycleSortOrderReverse,initializeSortButton,sortItems};